/**
 * The merged `unmodel/higgsfield` catalog — every route Higgsfield serves,
 * across all four addresses.
 *
 * **Importable from `./index.ts` and nowhere else.** This module is the union
 * of every slice, so anything that reaches it pulls in every route's row.
 * Each validator imports its own slice directly, which is what will keep
 * `unmodel/image` from shipping eighty-seven video rows.
 *
 * The image and video rows are generated by `scripts/codegen-higgsfield.ts`
 * from Higgsfield's own published per-route documents, snapshotted under
 * `data/higgsfield/routes/` — kind 3 in `src/providers/HAND_CATALOGS.md`.
 * Higgsfield is not in models.dev. The one hand row is Soul ID training
 * (`./character-train-models.ts`).
 *
 * Three things about every generated row, stated once:
 *
 * - **An id is a path.** `POST https://api.higgsfield.ai/<id>`. It names the
 *   route, hosted vendor included (`bytedance/seedance-2.5/text-to-video`);
 *   it is not a model name.
 * - **`cost` is present only where one figure is right for every request the
 *   route takes** — a flat per-image rate, or a per-second rate billed on the
 *   request's own `duration`. A rate keyed by resolution, billed on a source
 *   clip or surcharged for some requests is in `HIGGSFIELD_RATES` and is
 *   resolved per request by `higgsfieldCostUSD`. The one exception is the
 *   three priced Soul routes, whose `cost.perImage` carries the figure of the
 *   default resolution, 720p (owner decision, 2026-11-24; the provenance
 *   comment above each row says so).
 * - **A price can be contradicted.** Where a route's console document prints
 *   "Public pricing information is not available for this model." and its
 *   model page states a price, the route is unpriced: contradicting pages are
 *   not catalogued. Four routes are the exception, by owner decision of
 *   2026-11-24 — the three priced Soul routes and AI Influencer. Their row's
 *   comment carries a CAVEAT line, `HIGGSFIELD_RATES[id].contradicted` is the
 *   same fact as data, and an estimate computed from one comes with an
 *   `unconfirmed_cost` warning.
 */

import type { ModelInfo, ProviderInfo } from "../../core/catalog-types";
import { characterTrainModels } from "./character-train-models";
import { imageModels } from "./gen/models-image.gen";
import { videoModels } from "./gen/models-video.gen";

/**
 * Who this is, and where the key comes from.
 *
 * Both hold the `KEY_ID:KEY_SECRET` pair: `HF_CREDENTIALS` is the name
 * Higgsfield's JavaScript client is documented with and `HF_KEY` the one its
 * Python client is (https://docs.higgsfield.ai/docs/how-to/sdk.md, read
 * 2026-11-24). The header is `Authorization: Key <KEY_ID>:<KEY_SECRET>`.
 *
 * No `api`: that field is the OpenAI-compatible base, and Higgsfield has none.
 */
export const provider = {
  id: "higgsfield",
  name: "Higgsfield",
  env: ["HF_CREDENTIALS", "HF_KEY"],
  doc: "https://docs.higgsfield.ai/docs/llms.txt",
} as const satisfies ProviderInfo;

/**
 * Every Higgsfield route, keyed by id. The ids are disjoint by construction:
 * `scripts/codegen-higgsfield.ts` files each generated route under exactly one
 * output type, and does not generate the hand-written one.
 */
export const models = {
  ...characterTrainModels,
  ...imageModels,
  ...videoModels,
} as const satisfies Record<string, ModelInfo>;

export type HiggsfieldModelId = keyof typeof models;
